INSERT INTO networkelementsasis (opcoid,systemtypeid,orgeqpmanufacturerid,networkelementasplannedid,locationid,softwareproductnumber,softwareproductiondate,softwareinstalldate,dataacquisitiondate,manualoverride,elementdeploymentname,nodetype,platformtype,hardwaretype,softwarereleaseinformation,creationuser,modificationuser,elementmanager,dataacquisitionmethod) select DISTINCT op.opcoid,dc.systemtypeid,oem.orgeqpmanufacturerid,ass.networkelementasplannedid,ass.locationid,n.softwareproductnumber,n.softwareproductdate,n.softwareinstalldate,n.dataacquisitiondate,'0' as manualoverride,n.elementname,n.nodetype,n.platformtype,h.hardwaretype,n.softwarereleaseinformation,'1' as creationuser,'1' as modificationuser,n.spare1ossorenm,'Discovered' from networkelement n left join hardwareconfiguration h on h.networkelementid = n.networkelementid join opcos op on Replace(n.opco,'VODAFONE_UK','UK') = Upper(op.opco) join originalequipmentmanufacturers oem on UPPER(oem.originalequipmentmanufacturer) = UPPER(n.oem) join networkelementsasplanned ass on ass.opcoid = op.opcoid AND ass.orgeqpmanufacturerid = oem.orgeqpmanufacturerid AND ass.elementname = n.elementname join designcomponents dc on dc.designcomponentid = ass.designcomponentid;
COMMIT;
 